/// <summary>
/// This is a task service class for account status update job.
/// </summary>
class METAccountStatusUpdateTaskService extends METSysOperationTaskService
{
    METCustParameters metCustParameters;
    CustAccount       custAccount;
    guid              topPickingProcessId;

}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{
    METAccountStatusUpdateContract contract;

    super();

    // get the topPickingProcessId from the contract
    contract            = dataContract as METAccountStatusUpdateContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
    metCustParameters   = METCustParameters::Find();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METAccountStatusUpdateContract</c>.
/// </param>
public void process(METAccountStatusUpdateContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Runs tasks of the task service class.
/// </summary>
/// <param name = "_readPast">Table read past setting</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (custAccount)
            {
                this.execute();
            }
        }
        catch (Exception::Error)
        {
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Gets data from queue.
///</summary>
/// <param name = "_processId">Unique process Id.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METAccountStatusUpdateQueue queue;
    int                         backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    queue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock queue
            where queue.ProcessId == _processId;

        if (queue.RecId)
        {
            custAccount = queue.CustAccount;
            queue.delete();
        }
        else
        {
            custAccount = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (custAccount != '');
}

/// <summary>
/// Executes the process.
/// </summary>
private void execute()
{
    ttsbegin;

    boolean doUpdate;

    CustTable custTable = CustTable::find(custAccount, true);

    // Bug:402471 Only consider customers whose current CredManAccountStatusId is either
    // CustOnHoldAccountStatus or CustActiveAccountStatus. Other statuses are ignored.
    if (custTable.CredManAccountStatusId == metCustParameters.CustOnHoldAccountStatus
        || custTable.CredManAccountStatusId == metCustParameters.CustActiveAccountStatus)
    {  
        if (custTable.balanceAllCurrency() > custTable.CreditMax)
        {
            if (custTable.CredManAccountStatusId != metCustParameters.CustOnHoldAccountStatus)
            {
                custTable.CredManAccountStatusId = metCustParameters.CustOnHoldAccountStatus;
                doUpdate = true;
            }
        }
        else
        {
            if (custTable.CredManAccountStatusId != metCustParameters.CustActiveAccountStatus)
            {
                custTable.CredManAccountStatusId = metCustParameters.CustActiveAccountStatus;
                doUpdate = true;
            }
        }

        if (doUpdate)
        {
            custTable.credManAccountStatusUpdated();
            custTable.update();
        }
    }

    ttscommit;
}
